outputs.template:
#!version:1.0.0.1
## Generated by Oryk Provisioner for {{device.name}} ({{device.mac_colon}})
## {{system.date}} {{system.time}}

account.1.enable = 1
account.1.label = {{user.display_name}}
account.1.display_name = {{user.display_name}}
account.1.auth_name = {{sip.auth_username}}
account.1.user_name = {{sip.username}}
account.1.password = {{sip.password}}
account.1.sip_server.1.address = {{sip.domain}}
account.1.sip_server.1.port = {{sip.port}}
account.1.sip_server.1.expires = {{sip.register_expires|default:300}}
account.1.sip_server.1.transport_type = {{#if sip.secure}}2{{else}}0{{/if}}
account.1.outbound_proxy_enable = {{sip.outbound_proxy|bool:1,0}}
{{#if sip.outbound_proxy}}account.1.outbound_host = {{sip.outbound_proxy}}
account.1.outbound_port = {{sip.outbound_port|default:5060}}
{{/if}}
features.voice_mail.number.1 = {{sip.voicemail_number|default:*97}}
voice_mail.number.1 = {{sip.voicemail_number|default:*97}}

local_time.time_zone_name = {{system.timezone}}
local_time.ntp_server1 = {{system.ntp_server|default:pool.ntp.org}}

## Directory pulled from the PBX on every provisioning run
directory_setting.url = {{provisioning.root_url}}/{{device.mac}}-directory.xml

static.auto_provision.server.url = {{provisioning.root_url}}
static.auto_provision.mode = 1
